(()=>{
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const places=['신관 15층 엘베 앞','본관 15층 엘베 앞','신관 1층 로비','본관 1층 로비'];
let room=null,me=null,month=new Date();month.setDate(1);
const params=new URLSearchParams(location.search), roomId=params.get('room');
function note(s){showToast(s)}
async function api(path,method='GET',body){const res=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});let data;try{data=await res.json()}catch{throw Error('서버에 연결할 수 없습니다. 배포된 링크에서 다시 시도해 주세요.')}if(!res.ok)throw Error(data.error||'요청에 실패했습니다.');return data}
function err(e){$('#planError').textContent=e.message||String(e)}
function clearErr(){$('#planError').textContent=''}
function tab(id){document.querySelector(`.tab[data-tab="${id}"]`)?.click()}
function showRoom(){const isRestaurant=room.kind==='restaurant';$('#roomSetup').hidden=true;$('#roomContent').hidden=false;$('#roomTitle').textContent=room.title;$('#roomKind').textContent=isRestaurant?'식당 정하기':'점약 날짜 잡기';$('#roomCount').textContent=`${room.participants.length}/${room.headcount}명 참여 · ${room.participants.map(p=>p.name).join(', ')||'아직 참여자가 없어요'}`;
  $('#voteSection').hidden=!isRestaurant;$('#calendarSection').hidden=isRestaurant;$('#meetingSection').hidden=!isRestaurant;$('#shareUrl').textContent=location.href;$('#joinBox').hidden=!!me;$('#myBox').hidden=!me;$('#saveVote').hidden=!me;$('#finalBox').hidden=!me;
  if(me){const p=room.participants.find(x=>x.id===me.id);if(p){$('#myName').textContent=p.name;$('#myPlace').value=p.place||'';$('#myDuty').checked=p.on_duty;$('#myTime').value=p.available_time||'11:30';$('#myTime').disabled=p.on_duty;renderVotes(p);renderCalendar(p)}}
  renderResults();
}
function renderVotes(p){$('#voteList').innerHTML=restaurants.map(r=>`<div class="vote-item"><b>${esc(r.name)}</b><div class="vote-actions"><button data-id="${r.id}" data-choice="like" class="${p.likes.includes(r.id)?'liked':''}">♡ 가고 싶어요</button><button data-id="${r.id}" data-choice="dislike" class="${p.dislikes.includes(r.id)?'disliked':''}">× 오늘은 별로</button></div></div>`).join('')}
function chosen(){const likes=[],dislikes=[];document.querySelectorAll('#voteList .liked').forEach(x=>likes.push(Number(x.dataset.id)));document.querySelectorAll('#voteList .disliked').forEach(x=>dislikes.push(Number(x.dataset.id)));return{likes,dislikes}}
$('#voteList').addEventListener('click',e=>{const b=e.target.closest('button[data-choice]');if(!b)return;const row=b.closest('.vote-actions');const active=b.classList.contains(b.dataset.choice==='like'?'liked':'disliked');row.querySelectorAll('button').forEach(x=>x.classList.remove('liked','disliked'));if(!active)b.classList.add(b.dataset.choice==='like'?'liked':'disliked')});
function renderResults(){const count=room.participants.length,complete=count===room.headcount;$('#resultHint').textContent=complete?'모든 사람의 응답이 모였어요.':'응답을 기다리고 있어요. 중간 결과도 볼 수 있습니다.';
  if(room.kind==='restaurant'){let scores=restaurants.map(r=>({r,yes:room.participants.filter(p=>p.likes.includes(r.id)).length,no:room.participants.filter(p=>p.dislikes.includes(r.id)).length}));const candidates=scores.filter(x=>x.yes>0&&x.no===0).sort((a,b)=>b.yes-a.yes||a.r.name.localeCompare(b.r.name,'ko'));const excluded=scores.filter(x=>x.no>0).sort((a,b)=>b.no-a.no);
    $('#resultList').innerHTML=`<h3>오늘 갈 만한 식당</h3>${candidates.length?candidates.map(x=>`<div class="score-row"><span>${esc(x.r.name)}</span><small>❤️ ${x.yes}명</small></div>`).join(''):'<p class="plan-help">아직 모두가 괜찮다고 고른 식당이 없어요.</p>'}<div class="result-group"><h3>이번에는 제외된 식당</h3>${excluded.length?excluded.map(x=>`<div class="score-row"><span>${esc(x.r.name)}</span><small>× ${x.no}명</small></div>`).join(''):'<p class="plan-help">아직 없어요.</p>'}</div>`;
    $('#finalRestaurant').innerHTML='<option value="">최종 식당 선택</option>'+candidates.map(x=>`<option value="${x.r.id}">${esc(x.r.name)} · ❤️ ${x.yes}</option>`).join('');
    const spot=places.map(x=>({x,n:room.participants.filter(p=>p.place===x).length})).sort((a,b)=>b.n-a.n)[0];const latest=room.participants.map(p=>p.available_time).filter(Boolean).sort().at(-1);$('#meetingSuggestion').textContent=`추천: ${spot?.n?spot.x:'장소 응답 대기'} · ${latest?latest+' 이후':'시간 응답 대기'}`;
    $('#finalPlace').value=room.final_place||spot?.n&&spot.x||'';$('#finalTime').value=room.final_time||latest||'';$('#finalRestaurant').value=room.final_restaurant||'';
    $('#finalSummary').innerHTML=room.final_restaurant?`<strong>최종 결정 🎉</strong>${esc(restaurants.find(r=>r.id===room.final_restaurant)?.name||'')}<br>${esc(room.final_place||'장소 미정')} · ${esc(room.final_time||'시간 미정')}`:'';$('#finalSummary').hidden=!room.final_restaurant;
  }else{const scores={};room.participants.forEach(p=>p.dates.forEach(d=>scores[d]=(scores[d]||0)+1));const sorted=Object.entries(scores).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));$('#resultList').innerHTML=`<h3>모일 수 있는 날짜</h3>${sorted.length?sorted.map(([d,n])=>`<div class="score-row"><span>${esc(d)}</span><small>${n}/${room.headcount}명 가능 ${n===room.headcount?'✨':''}</small></div>`).join(''):'<p class="plan-help">아직 가능한 날짜를 선택한 사람이 없어요.</p>'}`;$('#finalDate').innerHTML='<option value="">최종 날짜 선택</option>'+sorted.map(([d,n])=>`<option value="${d}">${d} · ${n}명 가능</option>`).join('');$('#finalDate').value=room.final_date||'';$('#finalSummary').innerHTML=room.final_date?`<strong>점약 날짜 확정 🎉</strong>${esc(room.final_date)}`:'';$('#finalSummary').hidden=!room.final_date}
  $('#restaurantFinal').hidden=room.kind!=='restaurant';$('#calendarFinal').hidden=room.kind!=='calendar';
}
function renderCalendar(p){const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();$('#calendarTitle').textContent=`${y}년 ${m+1}월`;let html=['일','월','화','수','목','금','토'].map(x=>`<span>${x}</span>`).join('');for(let i=0;i<first;i++)html+='<button disabled></button>';for(let d=1;d<=days;d++){const date=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const n=room.participants.filter(x=>x.dates.includes(date)).length;html+=`<button type="button" data-date="${date}" title="${n}명 가능" class="${p.dates.includes(date)?'selected':''} ${n?'shared':''}">${d}${n?`<small> · ${n}</small>`:''}</button>`}$('#calendarGrid').innerHTML=html}
$('#calendarGrid').addEventListener('click',e=>{const b=e.target.closest('button[data-date]');if(b)b.classList.toggle('selected')});$('#prevMonth').onclick=()=>{month.setMonth(month.getMonth()-1);renderCalendar(room.participants.find(x=>x.id===me?.id)||{dates:[]})};$('#nextMonth').onclick=()=>{month.setMonth(month.getMonth()+1);renderCalendar(room.participants.find(x=>x.id===me?.id)||{dates:[]})};
$('#createRoom').onclick=async()=>{clearErr();try{const headcount=Number($('#headcount').value);const kind=$('#planKind').value;const data=await api('/sessions','POST',{kind,headcount,title:$('#planTitle').value});location.href=data.url}catch(e){err(e)}};
$('#joinRoom').onclick=async()=>{clearErr();try{const data=await api(`/sessions/${roomId}/participants`,'POST',{name:$('#joinName').value});me={id:data.participantId,token:data.token};localStorage.setItem('lunch-room-'+roomId,JSON.stringify(me));room=await api(`/sessions/${roomId}`);showRoom();note('참여했어요. 선택 내용을 저장해 주세요.')}catch(e){err(e)}};
$('#saveVote').onclick=async()=>{clearErr();try{const picks=chosen();const dates=[...document.querySelectorAll('#calendarGrid button.selected')].map(b=>b.dataset.date);const current=room.participants.find(p=>p.id===me.id);room=await api(`/sessions/${roomId}/participants`,'PUT',{participantId:me.id,token:me.token,likes:room.kind==='restaurant'?picks.likes:current.likes,dislikes:room.kind==='restaurant'?picks.dislikes:current.dislikes,dates:room.kind==='calendar'?[...new Set([...current.dates.filter(d=>d.slice(0,7)!==`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}`),...dates])]:current.dates,place:$('#myPlace').value,availableTime:$('#myTime').value,onDuty:$('#myDuty').checked});showRoom();note('내 응답을 저장했어요.')}catch(e){err(e)}};
$('#saveFinal').onclick=async()=>{clearErr();try{room=await api(`/sessions/${roomId}/final`,'PUT',{participantId:me.id,token:me.token,restaurant:Number($('#finalRestaurant').value),date:$('#finalDate').value,place:$('#finalPlace').value,time:$('#finalTime').value});showRoom();note('최종 결정을 저장했어요.')}catch(e){err(e)}};
$('#myDuty').onchange=e=>{if(e.target.checked){$('#myTime').value='12:00';$('#myTime').disabled=true}else $('#myTime').disabled=false};
$('#copyRoom').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);note('모임 링크를 복사했어요.')}catch{note('위 링크를 복사해 주세요.')}};
$('#refreshRoom').onclick=async()=>{try{room=await api(`/sessions/${roomId}`);showRoom();note('최신 응답을 불러왔어요.')}catch(e){err(e)}};
async function init(){if(!roomId)return;tab('planning');try{room=await api(`/sessions/${roomId}`);try{me=JSON.parse(localStorage.getItem('lunch-room-'+roomId)||'null')}catch{}if(me&&!room.participants.some(p=>p.id===me.id))me=null;showRoom();const target=['#joinBox','#calendarSection','#voteSection','#resultList'].includes(location.hash)?document.querySelector(location.hash):null;if(target&&!target.hidden)requestAnimationFrame(()=>target.scrollIntoView({block:'start'}))}catch(e){err(e)}}
init();
})();
